insert into public.services (num, title, icon_name, scope, skills, pills, order_index) values
('01', 'SHOPIFY & ECOMMERCE ENGINEERING', 'ShoppingBag', 'Building high-converting eCommerce experiences with custom Shopify themes, advanced Liquid development, storefront integrations, and tailored shopping functionality.', array['Custom Shopify Theme & Liquid Section Development', 'Storefront API, Custom Apps & Webhook Integrations', 'Advanced Product Variants, Pricing & Cart Logic', 'Custom Storefront Features & Third-Party Integrations', 'Conversion-Focused Product Pages & Checkout UX'], array['Shopify', 'Liquid', 'StorefrontAPI', 'CustomApps', 'Ecommerce'], 1),
('02', 'CUSTOM APPLICATIONS & API DEVELOPMENT', 'Code2', 'Developing tailored web applications and business tools using modern frontend frameworks, scalable backend architecture, and database-driven functionality.', array['React.js & Next.js Application Development', 'Node.js, Express.js & REST API Engineering', 'MongoDB & MySQL Database Integration', 'Custom Dashboards, Admin Panels & CRUD Systems', 'Third-Party API Integration, Authentication & Automation'], array['React', 'NextJS', 'NodeJS', 'MongoDB', 'APIIntegration'], 2),
('03', 'FRONTEND ENGINEERING, UI/UX & PROTOTYPING', 'Layout', 'Transforming ideas and design concepts into responsive, interactive interfaces through modern frontend engineering, rapid prototyping, and polished user experiences.', array['Responsive UI Development with React.js & Next.js', 'Interactive Prototypes & Functional MVP Development', 'Custom HTML, CSS, JavaScript & Component Systems', 'GSAP Animations, Scroll Interactions & Micro-Interactions', 'Performance Optimization, Accessibility & Core Web Vitals'], array['FrontendDevelopment', 'UIUX', 'Prototyping', 'GSAP', 'ResponsiveDesign'], 3),
('04', 'ECOMMERCE MARKETING & WORKFLOW AUTOMATION', 'Zap', 'Connecting eCommerce platforms with analytics, marketing tools, and automated workflows to streamline operations, improve customer engagement, and support business growth.', array['Klaviyo Email Marketing & Automated Customer Journeys', 'Marketing API Integrations & Workflow Automation', 'Google Analytics 4 & Conversion Tracking', 'Meta Pixel, Event Tracking & Marketing Attribution', 'Conversion Rate Optimization (CRO) & Technical SEO', 'Lead Capture, CRM Integration & Automated Notifications'], array['MarketingAutomation', 'Klaviyo', 'GA4', 'CRO', 'MetaPixel', 'WorkflowAutomation'], 4)
insert into public.workflow (id, step_id, step_label, tab_title, tagline, description, deliverables, timeline, milestone, order_index) values
('step-1', '01', 'STEP 01', 'Research & Wireframing', 'Uncovering user needs & establishing structural blueprints', 'Deep-dive discovery call, competitive benchmarking, user journey mapping, and low-fidelity wireframing to lock down layout architecture, conversion funnels, and sitemap before any visual design begins.', array['User Persona & Journey Mapping', 'Interactive Low-Fi Layout Wireframes', 'Information Architecture & Sitemap', 'Shopify / WordPress Feature Scope Audit'], '3-5 Days', 'Interactive Wireframe Approval', 1),
('step-2', '02', 'STEP 02', 'High-Fidelity Figma UI', 'Crafting pixel-perfect, responsive visual design systems', 'Creating modern, conversion-focused high-fidelity Figma prototypes following your brand guidelines. Establishing typography, color tokens, interactive components, PageFly/GemPages wireframes, and mobile-first layouts.', array['Pixel-Perfect Desktop & Mobile UI Designs', 'Interactive Figma Prototype & Micro-Animations', 'Reusable UI Component & Style Design System', 'PageFly & GemPages Custom Section Blueprints'], '4-6 Days', 'Figma Visual Design Sign-off', 2),
('step-3', '03', 'STEP 03', 'Custom WP & Shopify Build', 'Building responsive, standards-compliant custom code', 'Transforming approved designs into clean, responsive storefronts using custom Shopify Liquid, PageFly/GemPages sections, WordPress Elementor Pro Loop Builders, React.js UI modules, and custom CSS overrides.', array['Custom Shopify Liquid Theme Sections', 'Elementor Pro & Dynamic Loop Builder Setup', 'Fast AJAX Side-Cart Drawer & Variant Selectors', 'Clean HTML5 / CSS3 / ES6+ Component Integration'], '5-10 Days', 'Staging Site Build Review', 3),
('step-4', '04', 'STEP 04', 'Speed Optimization & Launch', 'Fine-tuning performance, cross-browser QA, and live deployment', 'Running Core Web Vitals optimization, image compression pipelines, cross-browser QA on staging, DNS/SSL setup, and final client walkthrough before going live with handover documentation.', array['Google PageSpeed & Core Web Vitals Optimization', 'Cross-Browser & Multi-Device QA Testing', 'Launch Checklist & DNS / SSL Configuration', 'Client Walkthrough Video & Handover Docs'], '2-4 Days', 'Production Site Launch', 4)
